/*
 * CB Model Projections team visual configuration.
 *
 * Default behavior is always the original CB abbreviation shield generated by
 * cb-team-visuals.js. No official team marks are bundled, downloaded, hotlinked,
 * or recreated by this repository.
 *
 * If CB later obtains a properly licensed team image, add one entry here:
 *
 *   "Pittsburgh Steelers": {
 *     abbreviation: "PIT",
 *     accent: "#6B7280",
 *     licensedImage: "assets/teams/licensed/pit.png",
 *     licensed: true
 *   }
 *
 * cb-team-visuals.js will use licensedImage only when licensed === true.
 * Without that explicit flag, the generated shield remains the default.
 */
window.CB_TEAM_ASSETS = Object.freeze({
  schemaVersion: 1,
  defaultMode: 'generated-badge',
  teams: Object.freeze({})
});
